-- B-06: strony prawne (regulamin, polityka prywatności, RODO) w CMS (info_pages).
--
-- Stopka frontu linkuje /info/regulamin, /info/polityka-prywatnosci i /info/rodo, a tabela nie miała tych
-- slugów (404 z publicznych linków). Treść jest tymczasowa (przeniesiona z dotychczasowej strony
-- zmierzymyczas.pl) i ma być edytowana przez administratorów w panelu CMS. Regulamin nie istnieje na starej
-- stronie, więc jest tylko szkieletem. show_in_footer=0: stopka ma własną, twardą sekcję „Prawne”.
-- Treść text-bloku to HTML po HtmlSanitizer (test LegalInfoPagesContractTest); blok ma "format":"html" (B-08).
--
-- Idempotentne: INSERT tylko gdy brak sluga (edycje administratora nie są nadpisywane).

INSERT INTO info_pages (id, title, slug, icon, description, content, published, show_in_footer, show_in_header, sort_order, created_at, updated_at)
SELECT 'page-legal-regulamin', 'Regulamin', 'regulamin', 'FileText', 'Regulamin serwisu zmierzymyczas.pl.', '[{"id":"hero","type":"hero","title":"Regulamin","content":"Regulamin serwisu zmierzymyczas.pl."},{"id":"body","type":"text","format":"html","title":"","content":"<p>Treść tymczasowa przeniesiona z dotychczasowej strony zmierzymyczas.pl – do weryfikacji i uzupełnienia przez administratora.</p><p>Regulamin serwisu zmierzymyczas.pl nie był dostępny na dotychczasowej stronie. Administrator powinien wkleić tutaj jego treść.</p>"}]', 1, 0, 0, 90, '2026-10-19T12:00:00+02:00', '2026-10-19T12:00:00+02:00'
FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM info_pages WHERE slug = 'regulamin');

INSERT INTO info_pages (id, title, slug, icon, description, content, published, show_in_footer, show_in_header, sort_order, created_at, updated_at)
SELECT 'page-legal-polityka-prywatnosci', 'Polityka prywatności', 'polityka-prywatnosci', 'Shield', 'Polityka prywatności serwisu zmierzymyczas.pl.', '[{"id":"hero","type":"hero","title":"Polityka prywatności","content":"Polityka prywatności serwisu zmierzymyczas.pl."},{"id":"body","type":"text","format":"html","title":"","content":"<p>Treść tymczasowa przeniesiona z dotychczasowej strony zmierzymyczas.pl – do weryfikacji i uzupełnienia przez administratora.</p><h2>1. Informacje podstawowe</h2><p>Niniejsza Polityka Prywatności określa zasady przetwarzania danych osobowych użytkowników serwisu internetowego <a href=\\"http://www.zmierzymyczas.pl\\">www.zmierzymyczas.pl</a></p><p>Administratorem danych osobowych jest:</p><p><strong>Dobre Czasy s.c.</strong><br>ul. Morcinka 43<br>45-531 Opole<br>Polska</p><p>Kontakt w sprawach związanych z ochroną danych osobowych:<br>E-mail: <a href=\\"mailto:biuro@zmierzymyczas.pl\\">biuro@zmierzymyczas.pl</a><br>Telefon: 501 146 066, 604 429 349</p><p>Administrator dokłada szczególnej staranności w celu ochrony prywatności użytkowników oraz bezpieczeństwa przekazywanych danych osobowych.</p><h2>2. Zakres zbieranych danych</h2><p>W zależności od celu korzystania z serwisu możemy przetwarzać następujące dane:</p><ul><li>imię i nazwisko,</li><li>adres e-mail,</li><li>numer telefonu,</li><li>data urodzenia,</li><li>płeć,</li><li>miejscowość,</li><li>klub sportowy,</li><li>numer startowy,</li><li>wyniki sportowe,</li><li>dane dotyczące płatności,</li><li>adres IP,</li><li>dane zapisywane w plikach cookies,</li><li>dane techniczne dotyczące urządzenia i przeglądarki.</li></ul><p>Podanie danych jest dobrowolne, jednak w niektórych przypadkach niezbędne do realizacji usługi, w szczególności zapisów na wydarzenia sportowe.</p><h2>3. Cele i podstawy prawne przetwarzania danych</h2><p>Dane osobowe przetwarzane są zgodnie z Rozporządzeniem Parlamentu Europejskiego i Rady (UE) 2016/679 (RODO).</p><p>Dane przetwarzamy w następujących celach:</p><h3>a) Realizacja zapisów na wydarzenia sportowe</h3><p>Podstawa prawna: art. 6 ust. 1 lit. b RODO – wykonanie umowy.</p><p>Obejmuje m.in.:</p><ul><li>rejestrację uczestników,</li><li>prowadzenie list startowych,</li><li>pomiar czasu,</li><li>publikację wyników,</li><li>kontakt organizacyjny,</li><li>obsługę płatności.</li></ul><h3>b) Realizacja obowiązków prawnych</h3><p>Podstawa prawna: art. 6 ust. 1 lit. c RODO.</p><p>Dotyczy to m.in. obowiązków księgowych i podatkowych.</p><h3>c) Marketing własnych usług</h3><p>Podstawa prawna: art. 6 ust. 1 lit. f RODO – prawnie uzasadniony interes administratora.</p><p>Obejmuje m.in.:</p><ul><li>wysyłkę informacji o wydarzeniach,</li><li>publikację materiałów promocyjnych,</li><li>prowadzenie statystyk i analiz.</li></ul><h3>d) Zgoda użytkownika</h3><p>Podstawa prawna: art. 6 ust. 1 lit. a RODO.</p><p>Dotyczy działań wymagających odrębnej zgody, np. marketingu partnerów lub zapisów do newslettera.</p><p>Zgodę można wycofać w dowolnym momencie.</p><h2>4. Publikacja wyników sportowych i wizerunku</h2><p>W związku z organizacją wydarzeń sportowych Administrator może publikować:</p><ul><li>listy startowe,</li><li>wyniki zawodów,</li><li>galerie zdjęć,</li><li>materiały video,</li><li>relacje z wydarzeń.</li></ul><p>Publikowane dane mogą obejmować:</p><ul><li>imię i nazwisko,</li><li>miejscowość,</li><li>klub,</li><li>kategorię wiekową,</li><li>osiągnięty wynik,</li><li>wizerunek utrwalony podczas wydarzenia.</li></ul><p>Publikacja wyników i relacji stanowi uzasadniony interes administratora związany z organizacją wydarzeń sportowych.</p><h2>5. Odbiorcy danych</h2><p>Dane mogą być przekazywane podmiotom współpracującym z Administratorem wyłącznie w zakresie niezbędnym do realizacji usług, w szczególności:</p><ul><li>organizatorom wydarzeń sportowych,</li><li>operatorom płatności,</li><li>dostawcom hostingu,</li><li>firmom świadczącym usługi IT,</li><li>podmiotom obsługującym mailing,</li><li>firmom księgowym,</li><li>podmiotom odpowiedzialnym za pomiar czasu.</li></ul><p>Dane mogą zostać udostępnione również uprawnionym organom publicznym, jeśli wymagają tego przepisy prawa.</p><h2>6. Okres przechowywania danych</h2><p>Dane będą przechowywane:</p><ul><li>przez okres niezbędny do realizacji usług,</li><li>przez okres wymagany przepisami prawa,</li><li>do momentu przedawnienia roszczeń,</li><li>do czasu wycofania zgody – w przypadku danych przetwarzanych na podstawie zgody.</li></ul><p>Wyniki sportowe mogą być przechowywane bezterminowo ze względu na historyczny i archiwalny charakter danych sportowych.</p><h2>7. Prawa użytkownika</h2><p>Każdej osobie, której dane dotyczą, przysługuje prawo do:</p><ul><li>dostępu do danych,</li><li>sprostowania danych,</li><li>usunięcia danych,</li><li>ograniczenia przetwarzania,</li><li>przenoszenia danych,</li><li>wniesienia sprzeciwu wobec przetwarzania,</li><li>cofnięcia zgody,</li><li>wniesienia skargi do Prezesa Urzędu Ochrony Danych Osobowych.</li></ul><p>Kontakt w sprawach dotyczących realizacji praw użytkownika: <a href=\\"mailto:biuro@zmierzymyczas.pl\\">biuro@zmierzymyczas.pl</a></p><h2>8. Pliki cookies</h2><p>Serwis wykorzystuje pliki cookies oraz podobne technologie w celu:</p><ul><li>prawidłowego działania strony,</li><li>utrzymania sesji użytkownika,</li><li>prowadzenia statystyk,</li><li>poprawy jakości usług,</li><li>działań marketingowych.</li></ul><p>Cookies mogą być wykorzystywane przez:</p><ul><li>narzędzia reklamowe Google,</li><li>inne narzędzia analityczne i marketingowe.</li></ul><p>Użytkownik może samodzielnie zarządzać ustawieniami cookies w swojej przeglądarce.</p><p>Jeżeli serwis korzysta z banera zgód cookies, użytkownik może zmienić swoje preferencje w dowolnym momencie.</p><h2>9. Profilowanie</h2><p>Dane użytkowników mogą być przetwarzane w sposób zautomatyzowany, w tym profilowane, wyłącznie w zakresie niezbędnym do działań marketingowych oraz statystycznych.</p><p>Profilowanie nie wywołuje skutków prawnych wobec użytkownika.</p><h2>10. Bezpieczeństwo danych</h2><p>Administrator stosuje odpowiednie środki techniczne i organizacyjne zapewniające ochronę przetwarzanych danych osobowych odpowiednią do zagrożeń oraz kategorii danych objętych ochroną.</p><h2>11. Linki do innych stron</h2><p>Serwis może zawierać odnośniki do innych stron internetowych. Administrator nie odpowiada za zasady prywatności obowiązujące na tych stronach.</p><h2>12. Zmiany polityki prywatności</h2><p>Administrator zastrzega sobie prawo do wprowadzania zmian w niniejszej Polityce Prywatności.</p><p>Aktualna wersja dokumentu jest zawsze dostępna na stronie: <a href=\\"http://www.zmierzymyczas.pl\\">www.zmierzymyczas.pl</a></p><h2>13. Data obowiązywania</h2><p>Polityka Prywatności obowiązuje od dnia: 26 maja 2026 r.</p>"}]', 1, 0, 0, 91, '2026-10-19T12:00:00+02:00', '2026-10-19T12:00:00+02:00'
FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM info_pages WHERE slug = 'polityka-prywatnosci');

